import React, { useState } from "react";
import "../App.css";

function AddListingPage() {
  const [form, setForm] = useState({
    title: "",
    description: "",
    price: "",
    location: "",
    propertyType: "",
    bedrooms: "",
    bathrooms: "",
    area: "",
    amenities: "",
    image: null,
  });

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    setForm({ ...form, [name]: files ? files[0] : value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log("Listing added:", form);
    alert("Your listing has been added successfully!");
    // You can later add API call to save the listing
  };

  return (
    <div className="add-listing-container">
      <h1 className="form-title">Add Your Property Listing</h1>

      <form className="add-listing-form" onSubmit={handleSubmit}>
        <label>Title</label>
        <input
          type="text"
          name="title"
          value={form.title}
          onChange={handleChange}
          placeholder="Enter title for your listing"
          required
        />

        <label>Description</label>
        <textarea
          name="description"
          value={form.description}
          onChange={handleChange}
          placeholder="Describe your property"
          required
        />

        <label>Price (₹)</label>
        <input
          type="number"
          name="price"
          value={form.price}
          onChange={handleChange}
          placeholder="Enter price"
          required
        />

        <label>Location</label>
        <input
          type="text"
          name="location"
          value={form.location}
          onChange={handleChange}
          placeholder="City, State"
          required
        />

        <label>Property Type</label>
        <select name="propertyType" value={form.propertyType} onChange={handleChange} required>
          <option value="">Select type</option>
          <option value="Flat">Flat</option>
          <option value="House">House</option>
          <option value="Hostel Room">Hostel Room</option>
          <option value="Shop">Shop</option>
          <option value="Land">Land</option>
        </select>

        <label>Bedrooms</label>
        <input
          type="number"
          name="bedrooms"
          value={form.bedrooms}
          onChange={handleChange}
          placeholder="Number of bedrooms"
        />

        <label>Bathrooms</label>
        <input
          type="number"
          name="bathrooms"
          value={form.bathrooms}
          onChange={handleChange}
          placeholder="Number of bathrooms"
        />

        <label>Area (sq ft)</label>
        <input
          type="number"
          name="area"
          value={form.area}
          onChange={handleChange}
          placeholder="Enter area in sq ft"
        />

        <label>Amenities</label>
        <input
          type="text"
          name="amenities"
          value={form.amenities}
          onChange={handleChange}
          placeholder="Pool, Parking, Gym, etc."
        />

        <label>Upload Image</label>
        <input type="file" name="image" accept="image/*" onChange={handleChange} />

        <button type="submit" className="submit-btn">
          Add Listing
        </button>
      </form>
    </div>
  );
}

export default AddListingPage;
